// The immediate-parent observation representation is common to both Node
// stores. Import the one funded transition producer directly, without a new
// forwarding Result or routing through the current compact Node/Automaton.
use super::super::transition_observation;

// Direct historical control is outside physical owner windows. Keep
// the full original transition producer on the old 232-byte enum and
// compare every field of every original corpus transition losslessly.
for block in &function.cleanup_plan.blocks {
    for transition in &block.transitions {
        let mut historical = ReplayBudget::unobserved();
        let mut common = ReplayBudget::unobserved();
        let expected = transition_observation_historical(
            &function, &mut historical, transition,
        );
        let actual = transition_observation(&function, &mut common, transition);
        match (&actual, &expected) {
            (Ok(None), Ok(None)) => {}
            (Ok(Some(actual)), Ok(Some(expected))) => assert!(
                crate::cleanup_plan::replay::compact_stage::observations_match(
                    actual, expected,
                )
            ),
            (Err(actual), Err(expected)) => assert_eq!(actual, expected),
            _ => panic!("complete historical transition mismatch: {actual:?} {expected:?}"),
        }
        assert_eq!(common.remaining, historical.remaining);
        assert_eq!(common.skeleton_spent, historical.skeleton_spent);
        drop((actual, expected, common, historical));
    }
}

macro_rules! canonical_staged {
    ($a:expr, $b:expr, $function:expr, $budget:expr) => {{
        decide!(staged_ordinal($a).cmp(&staged_ordinal($b)));
        match ($a, $b) {
            (
                StagedCopyResultSource::Body {
                    expression: xe,
                    instance: xi,
                },
                StagedCopyResultSource::Body {
                    expression: ye,
                    instance: yi,
                },
            ) => {
                decide!(text(xe.as_str(), ye.as_str(), $function, $budget)?);
                resolved_type(xi, yi, $function, $budget)
            }
            (
                StagedCopyResultSource::TryResidual {
                    expression: xe,
                    operand: xo,
                    source_instance: xs,
                    target_instance: xt,
                    result: xr,
                    ok_case: xoc,
                    ok_field: xof,
                    err_case: xec,
                    err_field: xef,
                },
                StagedCopyResultSource::TryResidual {
                    expression: ye,
                    operand: yo,
                    source_instance: ys,
                    target_instance: yt,
                    result: yr,
                    ok_case: yoc,
                    ok_field: yof,
                    err_case: yec,
                    err_field: yef,
                },
            ) => {
                decide!(text(xe.as_str(), ye.as_str(), $function, $budget)?);
                decide!(text(xo.as_str(), yo.as_str(), $function, $budget)?);
                decide!(resolved_type(xs, ys, $function, $budget)?);
                decide!(resolved_type(xt, yt, $function, $budget)?);
                decide!(text(xr.as_str(), yr.as_str(), $function, $budget)?);
                decide!(text(xoc.as_str(), yoc.as_str(), $function, $budget)?);
                decide!(text(xof.as_str(), yof.as_str(), $function, $budget)?);
                decide!(text(xec.as_str(), yec.as_str(), $function, $budget)?);
                decide!(text(xef.as_str(), yef.as_str(), $function, $budget)?);
                Ok(Ordering::Equal)
            }
            (
                StagedCopyResultSource::TryOptionNone {
                    expression: xe,
                    operand: xo,
                    source_instance: xs,
                    target_instance: xt,
                    option: xp,
                    some_case: xsc,
                    some_field: xsf,
                    none_case: xnc,
                },
                StagedCopyResultSource::TryOptionNone {
                    expression: ye,
                    operand: yo,
                    source_instance: ys,
                    target_instance: yt,
                    option: yp,
                    some_case: ysc,
                    some_field: ysf,
                    none_case: ync,
                },
            ) => {
                decide!(text(xe.as_str(), ye.as_str(), $function, $budget)?);
                decide!(text(xo.as_str(), yo.as_str(), $function, $budget)?);
                decide!(resolved_type(xs, ys, $function, $budget)?);
                decide!(resolved_type(xt, yt, $function, $budget)?);
                decide!(text(xp.as_str(), yp.as_str(), $function, $budget)?);
                decide!(text(xsc.as_str(), ysc.as_str(), $function, $budget)?);
                decide!(text(xsf.as_str(), ysf.as_str(), $function, $budget)?);
                decide!(text(xnc.as_str(), ync.as_str(), $function, $budget)?);
                Ok(Ordering::Equal)
            }
            _ => Err(mismatch($function)),
        }
    }};
}

fn compact_staged(
    a: &super::super::compact_stage::CopySource,
    b: &super::super::compact_stage::CopySource,
    function: &ResolvedFunction,
    budget: &mut ReplayBudget,
) -> Result<Ordering, Diagnostic> {
    use super::super::compact_stage::{CopySource, Residual};
    // Keep the original kind-work admission before new metadata payment.
    budget.charge(function, 1, "oracle staged source kind")?;
    // One-use query bank precedes both matches! receivers and the optional
    // residual payment. No nested staged Result survives on the residual arm.
    budget.reserve_bytes(
        function,
        2 * std::mem::size_of::<Result<(), Diagnostic>>()
            + 2 * std::mem::size_of::<&ResolvedFunction>()
            + 2 * std::mem::size_of::<&mut ReplayBudget>()
            + 2 * std::mem::size_of::<&str>()
            + 2 * std::mem::size_of::<usize>()
            + 2 * std::mem::size_of::<&CopySource>()
            + std::mem::size_of::<(&CopySource, &CopySource)>()
            + 3 * std::mem::size_of::<bool>(),
        "compact staged comparison query controls",
    )?;
    if matches!(a, CopySource::Residual(_)) && matches!(b, CopySource::Residual(_)) {
        // Two pattern refs, two accessor receivers, two returned canonical
        // refs and their two named lexical receivers, plus the two Box-field
        // borrows inside the accessors. No old Result credit.
        budget.reserve_bytes(
            function,
            4 * std::mem::size_of::<&Residual>()
                + 4 * std::mem::size_of::<&StagedCopyResultSource>()
                + 2 * std::mem::size_of::<&Box<StagedCopyResultSource>>(),
            "compact staged residual comparison references",
        )?;
    }
    match (a, b) {
        (CopySource::Residual(a), CopySource::Residual(b)) => {
            let a = a.canonical();
            let b = b.canonical();
            canonical_staged!(a, b, function, budget)
        }
        (
            CopySource::Body {
                expression: xe,
                instance: xi,
            },
            CopySource::Body {
                expression: ye,
                instance: yi,
            },
        ) => {
            decide!(text(xe.as_str(), ye.as_str(), function, budget)?);
            resolved_type(xi, yi, function, budget)
        }
        (CopySource::Body { .. }, CopySource::Residual(_)) => Ok(Ordering::Less),
        (CopySource::Residual(_), CopySource::Body { .. }) => Ok(Ordering::Greater),
    }
}

#[test]
fn compact_staged_order_preserves_canonical_fields_work_and_refusals() {
    use super::super::super::compact_stage::CopySource;
    let checked = crate::check(
        r#"module oracle.staged;
@id("result_path") fn result_path(value: Result<i64, i64>) -> Result<i64, i64> {
    let payload = value?;
    Result<i64, i64>::Ok { value: payload }
}
@id("option_path") fn option_path(value: Option<i64>) -> Option<i64> {
    let payload = value?;
    Option<i64>::Some { value: payload }
}
@id("main") fn main() -> i64 { 0 }
"#,
        "oracle-staged.spx",
    )
    .unwrap();
    let program = crate::hir::resolve(&checked).unwrap();
    let function = &program.functions[0];
    let sources: Vec<_> = program
        .functions
        .iter()
        .flat_map(|function| &function.cleanup_plan.blocks)
        .flat_map(|block| &block.transitions)
        .filter_map(|transition| match transition {
            CleanupTransition::StageCopyResult { source } => Some(source),
            _ => None,
        })
        .collect();
    for ordinal in 0..3 {
        assert!(sources
            .iter()
            .any(|source| staged_ordinal(source) == ordinal));
    }
    let mut construction = ReplayBudget::new();
    for a in &sources {
        for b in &sources {
            super::super::super::compact_stage::prepare!(function, &mut construction, *a, unwrap);
            let x = CopySource::new(function, &mut construction, (*a).clone()).unwrap();
            super::super::super::compact_stage::prepare!(function, &mut construction, *b, unwrap);
            let y = CopySource::new(function, &mut construction, (*b).clone()).unwrap();
            for work in [0, 1, 2, MAX_REPLAY_WORK_UNITS] {
                let mut original = ReplayBudget::new();
                let mut compact = ReplayBudget::new();
                original.remaining = work;
                compact.remaining = work;
                let expected = staged(a, b, function, &mut original);
                let actual = compact_staged(&x, &y, function, &mut compact);
                assert_eq!(actual, expected);
                assert_eq!(compact.remaining, original.remaining);
                assert_eq!(compact.skeleton_remaining, original.skeleton_remaining);
                if let Ok(order) = actual {
                    assert_eq!(order, a.cmp(b));
                }
            }
        }
    }
}

